"use strict";(self.webpackChunkstrapi_docs=self.webpackChunkstrapi_docs||[]).push([[86469],{38269:e=>{e.exports=JSON.parse('{"tag":{"label":"policies","permalink":"/tags/policies","allTagsPath":"/tags","count":8,"items":[{"id":"cms/api/graphql/advanced-policies","title":"Advanced policies for GraphQL","description":"Requests sent to the GraphQL API pass through Strapi\'s middlewares and policies system. Policies can be attached to resolvers to implement complex authorization rules, as shown in the present short guide.","permalink":"/cms/api/graphql/advanced-policies"},{"id":"cms/error-handling","title":"Error handling","description":"With Strapi\'s error handling feature it\'s easy to send and receive errors in your application.","permalink":"/cms/error-handling"},{"id":"cms/plugins/graphql","title":"GraphQL plugin","description":"Use a GraphQL endpoint in your Strapi project to fetch and mutate your content.","permalink":"/cms/plugins/graphql"},{"id":"cms/plugins-development/plugins-extension","title":"Plugins extension","description":"Existing plugins can be overriden by placing code in /src/extensions or using global register/bootstrap hooks. Instructions in this documentation cover reshaping plugin content-type schemas or server logic \u2014 altough upstream updates may break extensions.","permalink":"/cms/plugins-development/plugins-extension"},{"id":"cms/backend-customization/policies","title":"Policies","description":"Strapi policies are functions that execute specific logic on each request before it reaches the controller. Policies can be customized according to your needs.","permalink":"/cms/backend-customization/policies"},{"id":"cms/backend-customization/routes","title":"Routes","description":"Strapi routes handle requests to your content and are auto-generated for your content-types. Routes can be customized according to your needs.","permalink":"/cms/backend-customization/routes"},{"id":"cms/plugins-development/server-api","title":"Server API for plugins","description":"Overview of the Strapi Server API for plugins, with entry file, lifecycle hooks, routes, controllers, services, policies, middlewares, and configuration.","permalink":"/cms/plugins-development/server-api"},{"id":"cms/plugins-development/server-policies-middlewares","title":"Server policies & middlewares","description":"Guard plugin routes with policies and intercept requests with middlewares in the Strapi plugin Server API.","permalink":"/cms/plugins-development/server-policies-middlewares"}],"unlisted":false}}')}}]);